import{_ as t,o as a,c as d,ag as o}from"./chunks/framework.BKVF-9lJ.js";const g=JSON.parse('{"title":"mfe-forge init","description":"","frontmatter":{},"headers":[],"relativePath":"cli/init.md","filePath":"cli/init.md","lastUpdated":1791840224000}'),s={name:"cli/init.md"};function n(i,e,c,r,l,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="mfe-forge-init" tabindex="-1"><code>mfe-forge init</code> <a class="header-anchor" href="#mfe-forge-init" aria-label="Permalink to &quot;\`mfe-forge init\`&quot;">​</a></h1><p>Create a new MFE Forge workspace in a new directory.</p><h2 id="synopsis" tabindex="-1">Synopsis <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;Synopsis&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mfe-forge init [name] [options]</span></span></code></pre></div><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>init</code> creates <code>&lt;cwd&gt;/&lt;name&gt;/</code>, writes the workspace skeleton from the built-in <code>init</code> template, optionally initializes a git repository, and optionally installs dependencies. It is the only command that does not read an existing project configuration.</p><p>When <code>name</code> is <strong>omitted</strong>, <code>init</code> runs an interactive prompt. When <code>name</code> is <strong>given</strong>, no prompts are shown and every optional feature is disabled (see <a href="#interactive-vs-non-interactive">Interactive vs. non-interactive</a>).</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>No</td><td>Project name. Used as the directory name, the root <code>package.json</code> <code>name</code>, and the configuration <code>name</code>. Prompted for when omitted.</td></tr></tbody></table><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>-t</code>, <code>--template &lt;template&gt;</code></td><td>string</td><td><code>default</code></td><td>Accepted but <strong>currently ignored</strong>; the built-in <code>init</code> template is always used.</td></tr><tr><td><code>-pm</code>, <code>--package-manager &lt;pm&gt;</code></td><td><code>bun</code> | <code>pnpm</code> | <code>npm</code></td><td><code>bun</code></td><td>Package manager written to <code>defaults.packageManager</code> and used for the install step. Overridden by the prompt answer in interactive mode. The value is not validated by <code>init</code>; an unsupported value makes later commands fail configuration validation.</td></tr><tr><td><code>--skip-install</code></td><td>boolean</td><td><code>false</code></td><td>Do not run <code>&lt;pm&gt; install</code> after scaffolding.</td></tr><tr><td><code>--skip-git</code></td><td>boolean</td><td><code>false</code></td><td>Do not run <code>git init</code> or write <code>.gitattributes</code>.</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>boolean</td><td></td><td>Show help.</td></tr></tbody></table><h2 id="interactive-vs-non-interactive" tabindex="-1">Interactive vs. non-interactive <a class="header-anchor" href="#interactive-vs-non-interactive" aria-label="Permalink to &quot;Interactive vs. non-interactive&quot;">​</a></h2><p>When <code>name</code> is omitted, these prompts are shown:</p><table tabindex="0"><thead><tr><th>Prompt</th><th>Choices</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td>Project name</td><td>free text (required)</td><td></td><td>Directory and project name.</td></tr><tr><td>NPM organization</td><td>free text</td><td>empty</td><td>Written as <code>organization</code> in the config. Enter it <strong>without</strong> <code>@</code> (for example <code>acme</code>); generators prefix <code>@</code> themselves.</td></tr><tr><td>Package manager</td><td><code>bun</code>, <code>pnpm</code>, <code>npm</code></td><td><code>bun</code></td><td><code>defaults.packageManager</code>.</td></tr><tr><td>Features</td><td>Design System, Docker Support, GitHub Actions CI/CD, TypeScript Strict Mode</td><td>all checked</td><td>See below.</td></tr></tbody></table><p>How the selected features affect the output:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Effect</th></tr></thead><tbody><tr><td>TypeScript Strict Mode</td><td>Sets <code>strict</code>, <code>noUnusedLocals</code>, and <code>noUnusedParameters</code> to <code>true</code> in <code>tsconfig.base.json</code> (otherwise <code>false</code>).</td></tr><tr><td>GitHub Actions CI/CD</td><td>Keeps <code>.github/workflows/ci.yml</code> and sets <code>ci.provider: &#39;github&#39;</code> (otherwise the <code>.github</code> directory is removed and <code>ci.provider: &#39;none&#39;</code>).</td></tr><tr><td>Docker Support</td><td>Sets <code>ci.docker: true</code> in the config. No Dockerfile is generated.</td></tr><tr><td>Design System</td><td>Currently has no effect on the generated files. Use <a href="./generate#design-system"><code>generate design-system</code></a> instead.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Non-interactive defaults</p><p><code>mfe-forge init my-platform</code> (name given) enables <strong>no</strong> features: no CI workflow, <code>ci.docker: false</code>, non-strict TypeScript, and no <code>organization</code>.</p></div><h2 id="files-produced" tabindex="-1">Files produced <a class="header-anchor" href="#files-produced" aria-label="Permalink to &quot;Files produced&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;name&gt;/</span></span>
<span class="line"><span>├── apps/                 # empty</span></span>
<span class="line"><span>├── packages/             # empty</span></span>
<span class="line"><span>├── tools/                # empty</span></span>
<span class="line"><span>├── .github/workflows/ci.yml   # only with the CI feature</span></span>
<span class="line"><span>├── .gitattributes        # unless --skip-git (&quot;* text=auto eol=lf&quot;)</span></span>
<span class="line"><span>├── .gitignore</span></span>
<span class="line"><span>├── README.md</span></span>
<span class="line"><span>├── mfeforge.config.js</span></span>
<span class="line"><span>├── package.json</span></span>
<span class="line"><span>└── tsconfig.base.json</span></span></code></pre></div><p>The generated <code>package.json</code> declares <code>&quot;workspaces&quot;: [&quot;apps/*&quot;, &quot;packages/*&quot;]</code>, a <code>mfe-forge</code> dev dependency pinned to <code>^&lt;cli version&gt;</code>, and these scripts:</p><table tabindex="0"><thead><tr><th>Script</th><th>Command</th></tr></thead><tbody><tr><td><code>dev</code></td><td><code>mfe-forge dev</code></td></tr><tr><td><code>build</code></td><td><code>mfe-forge build</code></td></tr><tr><td><code>test</code></td><td><code>mfe-forge test</code></td></tr><tr><td><code>lint</code></td><td><code>eslint .</code></td></tr><tr><td><code>format</code></td><td><code>prettier --write .</code></td></tr><tr><td><code>type-check</code></td><td><code>tsc --noEmit</code></td></tr></tbody></table><p>The generated <code>mfeforge.config.js</code> sets <code>name</code>, <code>organization</code> (if given), <code>defaults</code>, <code>federation.shared</code>, <code>dev</code>, <code>testing</code>, and <code>ci</code>. Every omitted field takes its schema default; see the <a href="./../config">configuration reference</a>.</p><div class="warning custom-block"><p class="custom-block-title">Known template limitations</p><ul><li><code>testing.unit</code> and <code>testing.e2e</code> are always written as <code>&#39;none&#39;</code>, regardless of choices.</li><li>The workspace glob <code>apps/*</code> does not match apps generated at <code>apps/&lt;scope&gt;/&lt;name&gt;</code>. Change it to <code>&quot;apps/*/*&quot;</code> (the shape <a href="./doctor"><code>doctor</code></a> suggests) so <code>--filter</code>-based dev scripts can find generated apps.</li><li>No <code>pnpm-workspace.yaml</code> is written. pnpm ignores the <code>workspaces</code> field, so pnpm users must create <code>pnpm-workspace.yaml</code> with the same globs.</li><li>The generated CI workflow always uses Bun (<code>oven-sh/setup-bun</code>, <code>bun install</code>, <code>bun run lint|type-check|test</code>), even if another package manager was chosen.</li></ul></div><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Interactive setup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Non-interactive, pnpm, no install or git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-platform</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --package-manager</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip-install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip-git</span></span></code></pre></div><p>After success, <code>init</code> prints next steps using the selected package manager, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd my-platform</span></span>
<span class="line"><span>pnpm exec mfe generate host my-platform/host</span></span>
<span class="line"><span>pnpm exec mfe generate app my-platform/dashboard</span></span>
<span class="line"><span>pnpm run dev</span></span></code></pre></div><h2 id="failure-modes" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td><code>&lt;cwd&gt;/&lt;name&gt;</code> already exists</td><td><code>Directory &lt;name&gt; already exists</code>, exit <code>1</code>. Nothing is written.</td></tr><tr><td><code>git init</code> fails (git missing)</td><td><code>Initialization failed</code> plus the error, exit <code>1</code>. The partially created directory is <strong>not</strong> removed.</td></tr><tr><td><code>&lt;pm&gt; install</code> fails</td><td>Same as above. Files are left in place; fix the problem and run the install manually.</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./generate"><code>generate</code></a> — add hosts and apps to the new workspace</li><li><a href="./../config">Configuration reference</a></li><li><a href="./../quick-start">Quick start</a></li></ul>`,31)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
